import { loadFont as loadBrico } from "@remotion/google-fonts/BricolageGrotesque";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import React from "react";
import { AbsoluteFill, Easing, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// miny.site (Bruno): mini sites para o link da bio. Narração do próprio cliente (src/audio-1.mp3, 38,2 s).
// Jeito: vitrine com abertura em motion. O problema (0–12,5 s) é desenhado e genérico; o produto estreia no "Com a Miny"
// e daí em diante as gravações de tela dos sites dele ocupam o quadro inteiro, com lettering embaixo.
// Identidade do site: preto #08080A, roxo #7B3FE4, Bricolage Grotesque pesada em caixa alta + Instrument Serif itálica lilás.
// Tempos = tempos da narração; o vídeo começa LEAD antes.

const { fontFamily: BR } = loadBrico("normal", { weights: ["400", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SE } = loadSerif("italic", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: MA } = loadManrope("normal", { weights: ["300", "500", "700", "800"], subsets: ["latin", "latin-ext"] });

export const MINY_FPS = 30;
const LEAD = 0.3;
const VEND = 38.1;
const TAIL = 2.5;
export const MINY_FRAMES = Math.round((LEAD + VEND + TAIL) * MINY_FPS);

const VOID = "#08080A";
const CARD = "#15151A";
const PAPER = "#F4F5F7";
const PINK = "#0E0E12";
const ACC = "#7B3FE4";
const LAV = "#B9A2FF";
const MUTED = "#55596A";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.bezier(0.34, 1.56, 0.64, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const kb = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const COL = 840;
// largura média por letra: Bricolage 800 em caixa alta ≈ 0,64 · Instrument Serif itálica ≈ 0,40
const fitB = (s: string, max: number) => Math.min(max, Math.floor(COL / (s.length * 0.64)));
const fitS = (s: string, max: number) => Math.min(max, Math.floor(COL / (s.length * 0.4)));

// texto entra desfocado e um pouco maior, assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.42): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return { opacity: Math.min(1, e * 1.6) * (1 - o), filter: `blur(${((1 - e) * 14 + o * 12).toFixed(1)}px)`, transform: `scale(${(1.18 - 0.18 * e).toFixed(4)})` };
};
const Caps: React.FC<{ t: number; at: number; out?: number; s: string; max?: number; color?: string }> = ({ t, at, out, s, max = 120, color = "#FFFFFF" }) => {
  const size = fitB(s, max);
  return <div style={{ fontFamily: BR, fontWeight: 800, fontSize: size, lineHeight: 0.98, letterSpacing: "-0.035em", color, whiteSpace: "nowrap", textAlign: "center", paddingBottom: size * 0.04, ...blurIn(t, at, out) }}>{s}</div>;
};
const Ital: React.FC<{ t: number; at: number; out?: number; s: string; max?: number; color?: string }> = ({ t, at, out, s, max = 120, color = LAV }) => {
  const size = fitS(s, max);
  return <div style={{ fontFamily: SE, fontStyle: "italic", fontSize: size, lineHeight: 1.0, color, whiteSpace: "nowrap", textAlign: "center", paddingBottom: size * 0.06, ...blurIn(t, at, out, 0.5) }}>{s}</div>;
};
const Block: React.FC<{ children: React.ReactNode; top: number; gap?: number }> = ({ children, top, gap = 4 }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
const Glow: React.FC<{ x?: number; y: number; r: number; a: number }> = ({ x = 540, y, r, a }) => (
  <div style={{ position: "absolute", left: x - r, top: y - r, width: r * 2, height: r * 2, borderRadius: "50%", background: `radial-gradient(circle, rgba(123,63,228,${a}) 0%, rgba(100,48,196,${a * 0.4}) 38%, rgba(8,8,10,0) 70%)` }} />
);

// símbolo do logo (desenhado a partir do fav-icon): duas metades e a barra do meio
const LinkIcon: React.FC<{ w: number; join?: number; bar?: number; color?: string }> = ({ w, join = 1, bar = 1, color = "#FFFFFF" }) => {
  const dx = (1 - join) * 120;
  return (
    <svg width={w} height={(w * 366) / 640} viewBox="130 267 640 366" style={{ display: "block", overflow: "visible" }}>
      <g fill="none" stroke={color} strokeWidth={60} strokeLinecap="round">
        <path d="M390 327 H300 A122.5 122.5 0 0 0 300 572 H390" transform={`translate(${-dx} 0)`} />
        <path d="M510 327 H600 A122.5 122.5 0 0 1 600 572 H510" transform={`translate(${dx} 0)`} />
        <path d="M365 450 H535" pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - bar} opacity={bar > 0.01 ? 1 : 0} />
      </g>
    </svg>
  );
};
const Wordmark: React.FC<{ size: number; color?: string }> = ({ size, color = "#FFFFFF" }) => (
  <div style={{ display: "flex", alignItems: "baseline", fontSize: size, color, whiteSpace: "nowrap", lineHeight: 1 }}>
    <span style={{ fontFamily: MA, fontWeight: 300, transform: "skewX(-12deg)", display: "inline-block", letterSpacing: "-0.02em" }}>miny</span>
    <span style={{ fontFamily: MA, fontWeight: 800, letterSpacing: "-0.03em" }}>.site</span>
  </div>
);

// ───────── peças genéricas do "link comum" (sem marca nenhuma) ─────────
const Bar: React.FC<{ w: number; h?: number; c?: string }> = ({ w, h = 20, c = "rgba(255,255,255,0.16)" }) => <div style={{ width: w, height: h, borderRadius: h / 2, background: c }} />;
const ProfileCard: React.FC<{ t: number; miny?: boolean; tap?: number }> = ({ t, miny, tap = -1 }) => {
  const press = tap < 0 ? 0 : Math.sin(Math.PI * lin(t, tap, tap + 0.28));
  return (
    <div style={{ width: 760, padding: "56px 60px 64px", borderRadius: 44, background: CARD, border: "1px solid rgba(255,255,255,0.09)", display: "flex", flexDirection: "column", alignItems: "center", gap: 26, boxShadow: "0 40px 90px rgba(0,0,0,0.55)" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 34, alignSelf: "stretch" }}>
        <div style={{ width: 150, height: 150, borderRadius: "50%", background: miny ? `linear-gradient(135deg, ${ACC}, ${LAV})` : "rgba(255,255,255,0.14)", padding: 6 }}>
          <div style={{ width: "100%", height: "100%", borderRadius: "50%", background: "#2A2A33" }} />
        </div>
        <div style={{ display: "flex", gap: 40 }}>
          {[0, 1, 2].map((i) => <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 12 }}><Bar w={70} h={26} c="rgba(255,255,255,0.32)" /><Bar w={90} h={14} /></div>)}
        </div>
      </div>
      <div style={{ alignSelf: "stretch", display: "flex", flexDirection: "column", gap: 16 }}>
        <Bar w={300} h={24} c="rgba(255,255,255,0.4)" />
        <Bar w={560} h={16} />
        <Bar w={470} h={16} />
      </div>
      <div style={{ alignSelf: "stretch", height: 104, borderRadius: 26, display: "flex", alignItems: "center", justifyContent: "center", gap: 18,
        background: miny ? ACC : "rgba(255,255,255,0.07)", border: miny ? "none" : "2px dashed rgba(255,255,255,0.22)",
        transform: `scale(${(1 - press * 0.05).toFixed(3)})`, boxShadow: miny ? `0 0 ${40 + press * 40}px rgba(123,63,228,0.45)` : undefined }}>
        <LinkIcon w={58} color={miny ? "#FFFFFF" : "rgba(255,255,255,0.45)"} />
        <div style={{ fontFamily: MA, fontWeight: 700, fontSize: 40, color: miny ? "#FFFFFF" : "rgba(255,255,255,0.5)" }}>{miny ? "miny.site/seunome" : "link.bio/seuperfil"}</div>
      </div>
    </div>
  );
};
const Cursor: React.FC<{ x: number; y: number; press: number }> = ({ x, y, press }) => (
  <div style={{ position: "absolute", left: x, top: y, transform: `scale(${(1 - press * 0.18).toFixed(3)})`, transformOrigin: "10px 6px" }}>
    <svg width={86} height={104} viewBox="0 0 43 52"><path d="M4 2 L4 40 L14 31 L21 48 L28 45 L21 29 L35 29 Z" fill="#FFFFFF" stroke="#0E0E12" strokeWidth={2.5} strokeLinejoin="round" /></svg>
  </div>
);
const XMark: React.FC<{ s: number; p: number; c?: string }> = ({ s, p, c = "#FF5A6E" }) => (
  <svg width={s} height={s} viewBox="0 0 40 40" style={{ display: "block" }}>
    <circle cx="20" cy="20" r="18" fill="none" stroke={c} strokeWidth={3} opacity={0.9} />
    <g stroke={c} strokeWidth={4} strokeLinecap="round">
      <path d="M13 13 L27 27" pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - Math.min(1, p * 2)} />
      <path d="M27 13 L13 27" pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - Math.max(0, p * 2 - 1)} />
    </g>
  </svg>
);

// ───────── cenas desenhadas ─────────
// 1 · "Você ainda usa só um link na bio?"  (cartão de perfil genérico voa para dentro; câmera mergulha no link)
const S1: React.FC<{ t: number }> = ({ t }) => {
  const c = kb(t, -0.3, 0.8);
  const cam = 1.0 + 0.1 * io(t, 0.0, 2.4) + 0.9 * io(t, 2.25, 2.75);
  return (
    <AbsoluteFill style={{ background: VOID }}>
      <Glow y={1240} r={720} a={0.22} />
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)})`, transformOrigin: "540px 1450px" }}>
        <Block top={370} gap={0}>
          <Caps t={t} at={-0.2} s="VOCÊ AINDA USA" max={96} />
          <Caps t={t} at={1.05} s="SÓ UM LINK" max={150} />
          <Ital t={t} at={1.75} s="na bio?" max={150} />
        </Block>
        <div style={{ position: "absolute", left: 160, top: 920, opacity: Math.min(1, c * 1.5), transform: `translateY(${((1 - c) * 520).toFixed(1)}px) rotate(${((1 - c) * -9).toFixed(2)}deg)` }}>
          <ProfileCard t={t} />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// 2 · "Então você está perdendo cliente. Todo dia."  (pessoas indo embora; a semana inteira)
const S2: React.FC<{ t: number }> = ({ t }) => {
  const cam = 1.06 - 0.06 * io(t, 2.55, 5.4);
  const days = ["SEG", "TER", "QUA", "QUI", "SEX", "SÁB", "DOM"];
