      </Block>
      {/* cinco pessoas: entram juntas e vão saindo pela direita, uma a uma */}
      <div style={{ position: "absolute", left: 120, width: COL, top: 1190, display: "flex", justifyContent: "center", gap: 34 }}>
        {[0, 1, 2, 3, 4].map((i) => {
          const e = kb(t, 2.7 + i * 0.05, 0.45);
          const g = io(t, 3.3 + i * 0.16, 3.85 + i * 0.16);
          return (
            <div key={i} style={{ width: 128, height: 128, borderRadius: "50%", background: CARD, border: "1px solid rgba(255,255,255,0.12)", display: "flex", alignItems: "center", justifyContent: "center",
              opacity: Math.min(1, e * 1.6) * (1 - g), transform: `translate(${(g * 260).toFixed(1)}px, ${((1 - e) * 60 + g * 40).toFixed(1)}px) scale(${(1 - g * 0.3).toFixed(3)})` }}>
              <svg width={64} height={64} viewBox="0 0 32 32"><circle cx="16" cy="11" r="6.5" fill="rgba(255,255,255,0.75)" /><path d="M4 30 C 5 21, 27 21, 28 30 Z" fill="rgba(255,255,255,0.75)" /></svg>
            </div>
          );
        })}
      </div>
      <Block top={1120} gap={36}>
        <Ital t={t} at={4.45} s="todo dia." max={150} />
        <div style={{ display: "flex", gap: 14 }}>
          {days.map((d, i) => {
            const e = kb(t, 4.55 + i * 0.07, 0.4);
            return <div key={d} style={{ width: 106, height: 104, borderRadius: 20, border: "2px solid rgba(255,90,110,0.55)", background: "rgba(255,90,110,0.08)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: MA, fontWeight: 800, fontSize: 31, color: "#FF8A98", opacity: Math.min(1, e * 1.6), transform: `scale(${(0.6 + 0.4 * e).toFixed(3)})` }}>{d}</div>;
          })}
        </div>
      </Block>
    </AbsoluteFill>
  );
};

// 3 · "Porque um link simples não vende."  (página clara: três botões iguais e sem graça; o toque não leva a nada)
const S3: React.FC<{ t: number }> = ({ t }) => {
  const cam = 1.08 - 0.08 * io(t, 5.45, 7.7);
  const tap = 6.9;
  const mv = io(t, 5.9, 6.75);
  const press = Math.sin(Math.PI * lin(t, tap - 0.05, tap + 0.25));
  const shake = Math.sin((t - 7.0) * 60) * 14 * (t > 7.0 && t < 7.4 ? 1 - (t - 7.0) / 0.4 : 0);
  return (
    <AbsoluteFill style={{ background: PAPER, transform: `scale(${cam.toFixed(4)})` }}>
      <Block top={400} gap={4}>
        <Caps t={t} at={5.6} s="UM LINK" max={150} color={PINK} />
        <Caps t={t} at={6.2} s="SIMPLES" max={150} color={PINK} />
        <Ital t={t} at={6.75} s="não vende." max={150} color={ACC} />
      </Block>
      <div style={{ position: "absolute", left: 160, width: 760, top: 1000, display: "flex", flexDirection: "column", gap: 30, transform: `translateX(${shake.toFixed(1)}px)` }}>
        {["Link 1", "Link 2", "Link 3"].map((s, i) => {
          const e = kb(t, 5.55 + i * 0.1, 0.45);
          return (
            <div key={s} style={{ height: 136, borderRadius: 68, border: "3px solid rgba(14,14,18,0.18)", background: "#FFFFFF", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: MA, fontWeight: 700, fontSize: 48, color: MUTED,
              opacity: Math.min(1, e * 1.6), transform: `translateY(${((1 - e) * 80).toFixed(1)}px) scale(${(i === 1 ? 1 - press * 0.04 : 1).toFixed(3)})` }}>{s}</div>
          );
        })}
      </div>
      <Cursor x={interpolate(mv, [0, 1], [880, 560])} y={interpolate(mv, [0, 1], [1720, 1180])} press={press} />
    </AbsoluteFill>
  );
};

// 4 · "Ele não mostra quem você é, não organiza suas ofertas e nem passa confiança."  (um item por batida)
const S4: React.FC<{ t: number }> = ({ t }) => {
  const rows: [number, string, string][] = [[7.94, "mostra", "quem você é"], [9.36, "organiza", "suas ofertas"], [11.3, "passa", "confiança"]];
  // câmera vai até cada item quando ele é falado
  const camY = interpolate(t, [7.7, 8.0, 9.3, 9.65, 11.2, 11.55, 12.6], [0, 50, 50, -30, -30, -110, -125], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: VOID }}>
      <Glow y={1100} r={680} a={0.15} />
      <AbsoluteFill style={{ transform: `translateY(${camY.toFixed(1)}px) scale(${(1.0 + 0.1 * io(t, 7.7, 12.6)).toFixed(4)})` }}>
        <Block top={360} gap={0}>
          <Caps t={t} at={7.78} s="ELE NÃO..." max={170} />
        </Block>
        <div style={{ position: "absolute", left: 120, width: COL, top: 700, display: "flex", flexDirection: "column", gap: 44 }}>
          {rows.map(([at, verb, what], i) => {
            const e = kb(t, at, 0.5);
            return (
              <div key={i} style={{ height: 250, borderRadius: 36, background: CARD, border: "1px solid rgba(255,255,255,0.09)", display: "flex", alignItems: "center", gap: 40, padding: "0 50px",
                opacity: Math.min(1, e * 1.6), transform: `translateX(${((1 - e) * (i % 2 ? 300 : -300)).toFixed(1)}px)` }}>
                <XMark s={110} p={lin(t, at + 0.25, at + 0.7)} />
                <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
