};

// ───────── entradas de cena (todas diferentes em sequência) ─────────
type Enter = "whip" | "up" | "circle" | "fade" | "left" | "right" | "punch" | "split" | "blur";
const enter = (kind: Enter, p: number, cx = 540, cy = 960): React.CSSProperties => {
  const e = OUT(p);
  switch (kind) {
    case "whip": return { opacity: Math.min(1, p * 3), transform: `scale(${(0.82 + 0.18 * e).toFixed(4)})`, filter: p < 1 ? `blur(${((1 - e) * 20).toFixed(1)}px)` : undefined };
    case "up": return { transform: `translateY(${((1 - e) * 1920).toFixed(1)}px)` };
    case "circle": return { clipPath: `circle(${(e * 1400).toFixed(1)}px at ${cx}px ${cy}px)` };
    case "fade": return { opacity: e };
    case "left": return { transform: `translateX(${((1 - e) * 1080).toFixed(1)}px)` };
    case "right": return { transform: `translateX(${((1 - e) * -1080).toFixed(1)}px)` };
    case "punch": return { opacity: Math.min(1, p * 4), transform: `scale(${(1.35 - 0.35 * e).toFixed(4)})` };
    case "split": return { clipPath: `inset(${((1 - e) * 50).toFixed(2)}% 0 ${((1 - e) * 50).toFixed(2)}% 0)` };
    case "blur": return { opacity: Math.min(1, p * 2.5), filter: p < 1 ? `blur(${((1 - e) * 24).toFixed(1)}px)` : undefined, transform: `scale(${(1.08 - 0.08 * e).toFixed(4)})` };
  }
};
type Scene = { a: number; b: number; d: number; kind: Enter; cx?: number; cy?: number; el: (t: number) => React.ReactNode };
const clipScene = (id: string, kind: Enter, d = 0.38, cx?: number, cy?: number): Scene => {
  const c = CLIPS.find((x) => x.id === id)!;
  return { a: c.a, b: c.b, d, kind, cx, cy, el: (t) => <SiteClip t={t} c={c} /> };
};
