const Corpo: React.FC = () => {
  const t = useCurrentFrame() / MINY_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: VOID }}>
      {SCENES.map((s, i) => {
        if (t < s.a - 0.02 || t > s.b + 0.6) return null;
        const p = lin(t, s.a, s.a + s.d);
        return <AbsoluteFill key={i} style={{ overflow: "hidden", ...enter(s.kind, p, s.cx, s.cy) }}>{s.el(t)}</AbsoluteFill>;
      })}
    </AbsoluteFill>
  );
};
